  ar:{dir:'rtl',cod:'الدفع عند الاستلام',delivery:'التوصيل لجميع المدن',form:'اطلب دابا وخلص ملي توصلك',name:'الاسم الكامل',phone:'رقم الهاتف',city:'المدينة',address:'العنوان',offer:'اختار العرض',cta:'اطلب الآن',thanks:'شكرا! توصلنا بالطلب ديالك، وغادي نتصلو بيك قريب باش نأكدوه.',back:'رجوع للصفحة',sending:'كنصيفطو...',errors:{name:'دخل الاسم ديالك',phone:'دخل رقم هاتف صحيح',city:'دخل المدينة',address:'دخل العنوان',offer:'اختار العرض'},wa:'سولنا فـ WhatsApp',piece:'حبة',problem:'واش عندك هاد المشكل؟',offerT:'عرض خاص',why:'علاش تختارو؟',faq:'أسئلة متكررة'},
